import math
import unittest
from solution import distance_tint, colour_hex


class ColourTests(unittest.TestCase):
    def test_zero_steps_and_hex(self):
        origin = (0, 127, 255)
        self.assertEqual(distance_tint(0, origin), origin)
        self.assertEqual(colour_hex(origin), "#007FFF")
        self.assertEqual(origin, (0, 127, 255))

    def test_formula_and_rounding(self):
        origin = (10, 100, 200)
        steps, floor, rate = 3, 0.2, 0.5
        factor = floor + (1 - floor) * math.exp(-rate * steps)
        expected = tuple(round(255 - (255 - channel) * factor) for channel in origin)
        result = distance_tint(steps, origin, floor, rate)
        self.assertEqual(result, expected)
        self.assertTrue(all(type(channel) is int for channel in result))

    def test_boundary_parameters(self):
        self.assertEqual(distance_tint(50, (1, 2, 3), floor=1, rate=2), (1, 2, 3))
        result = distance_tint(1000, (0, 0, 0), floor=0, rate=1)
        self.assertEqual(result, (255, 255, 255))
        near_limit = distance_tint(1000, (0, 0, 0), floor=0.08, rate=0.65)
        self.assertEqual(near_limit, (235, 235, 235))

    def test_steps_validation(self):
        for value in (True, 1.0, "1", None):
            with self.assertRaises(TypeError): distance_tint(value, (0, 0, 0))
        with self.assertRaises(ValueError): distance_tint(-1, (0, 0, 0))

    def test_rgb_validation_for_both_functions(self):
        malformed = [[], (), (1, 2), (1, 2, 3, 4), (1, 2, True), (1, 2, 3.0), (-1, 2, 3), (1, 2, 256)]
        for rgb in malformed:
            for function in (distance_tint, colour_hex):
                with self.subTest(rgb=rgb, function=function.__name__):
                    with self.assertRaises((TypeError, ValueError)):
                        function(0, rgb) if function is distance_tint else function(rgb)

    def test_floor_and_rate_validation(self):
        for value in (True, "0.5", None):
            with self.assertRaises(TypeError): distance_tint(1, (0, 0, 0), floor=value)
        for value in (-0.1, 1.1):
            with self.assertRaises(ValueError): distance_tint(1, (0, 0, 0), floor=value)
        for value in (True, "1", None):
            with self.assertRaises(TypeError): distance_tint(1, (0, 0, 0), rate=value)
        for value in (0, -0.1):
            with self.assertRaises(ValueError): distance_tint(1, (0, 0, 0), rate=value)


if __name__ == "__main__":
    unittest.main()

